         }
        .security_dropdown {
          position: relative;
          display: inline-block;
          margin-left:16px;
        }

        .security_dropbtn {
          background-color: #FFFFFF;
          color: #333333;
          padding: 12px 32px 12px 16px;
          font-weight: 500;
          font-size: 15px;
          line-height: 18px;
          border: 1px solid #D5D5D5;
          cursor: pointer;
          border-radius: 5px;
          width: 330px;
          height:45px;
          text-align: left;
          overflow: auto;
        }

        .security_dropdown_content {
          display: none;
          position: absolute;
          background-color: #FFFFFF;
          min-width: 330px;
          z-index: 1;
          border: 1px solid #D4D4D4;
          box-shadow: 0px 4px 16px rgba(0, 0, 0, 0.12);
          border-radius: 4px;
          padding: 8px 0px;
        }

        .security_dropdown_content div {
          color: #333333;;
          padding: 8px 20px;
          text-decoration: none;
          display: block;
          font-weight: 400;
          font-size: 15px;
          line-height: 23px;
        }

        .security_dropdown_content div:hover {
        background-color:#F0F0F0;
        cursor: pointer;
        }

        .security-caret {
            display: inline-block;
            width: 0;
            height: 0;
            vertical-align: middle;
            border-top: 6px solid #171616;
            border-right: 6px solid transparent;
            border-left: 6px solid transparent;
            position: absolute;
            top: 52%;
            left: 87%;
            transform: translateY(-50%);
        }

        .security-caret:hover{cursor:pointer;}

        .security-service-label {
            display: flex;
            flex-direction: row;
            justify-content: flex-end;
            align-items: center;
            margin-right: 4px;
        }
            .security-subheader{
                font-weight: 400;
                font-size: 15px;
                line-height: 20px;
                color: #323E48;
                margin-top:30px;
                margin-bottom: 24px;
            }
            .ftnt-security-progress::-moz-range-thumb{
          width: 34.57%;
          height: 4px;
          background: #DA291C;
        }

          .ftnt-security-progress::-webkit-slider-thumb {
          -webkit-appearance: none;
          appearance: none;
          width: 30%;
          height: 4px;
          background: #DA291C;
        }

            .ftnt-security-progress {
            width: 100%;
            height: 4px;
            border-radius: 3px;
            overflow: hidden;
            margin: auto;
            background-color: #dcdcdc;
            background-image: linear-gradient(to right, #DA291C, #DA291C);
            background-repeat: no-repeat;
            background-size: 0 100%;
            -webkit-appearance: none;
          outline: none;
          opacity: 1;
          -webkit-transition: 1s;
          transition: opacity 1s;
        }
        .ftnt-slide-security-prev {
            background-position: center;
            transform: rotate(0deg);
            background-repeat:no-repeat;
            background-image: url(/content/dam/fortinet/images/ngfw/slider-arrow.svg);
            width: 60px;
            height: 60px;
            background-color: transparent;
            border: none;
            padding-bottom: 10px;
            margin-left : -12px;
        }
        .ftnt-slide-security-next {
            background-position: center;
             transform: rotate(180deg);
             background-repeat:no-repeat;
            background-image: url(/content/dam/fortinet/images/ngfw/slider-arrow.svg);
            width: 60px;
            height: 60px;
            background-color: transparent;
            border: none;
            padding-bottom: 10px;
            margin-right: -8px;
        }

        .ftnt-arrow-security{
            display: flex;
            flex-direction: row;
        }

            .security-service-filter {
                font-size:13px;
                font-weight:700;
            }

            .security-service-icon + span {
                font-size:14px!important;
            }
